import * as React from "react";
import cn from "classnames";
import Card from "../Card";
import Header from "../Header";
import Progress from "../Progress";

export type ProgressCardProps = {
  readonly className?: string;
  readonly header?: React.ReactNode;
  readonly content?: React.ReactNode;
  readonly progressColor?: string;
  readonly progressWidth?: number;
};

function ProgressCard({
  className,
  header,
  content,
  progressColor,
  progressWidth,
}: ProgressCardProps): React.ReactElement {
  const classes = cn(className);
  return (
    <Card className={classes}>
      <Card.Body className="text-center">
        <Header size={5}>{header}</Header>
        <div className="display-4 font-weight-bold mb-4">{content}</div>
        <Progress size="sm">
          <Progress.Bar color={progressColor} width={progressWidth} />
        </Progress>
      </Card.Body>
    </Card>
  );
}

ProgressCard.displayName = "ProgressCard";

export default ProgressCard;
